INSERT INTO `voc_book` VALUES (1854000040400068610, 1853715495989743617, '分频词汇', '美国当代语料库 10000', NULL, NULL, NULL, 4791, 'COCA美国当代英语语料库（全称Corpus of Contemporary American English)是当今世界上最大的在线免费英语平衡语料库，由美国杨百翰大学语言学教授Mark Davies在2008年建立，主要为语言学习者和语言学家了解单词、短语以及句子结构的频率及进行相关信息比较而设计。 *缺失部分单词为同一个单词不同词性在美国语料库中判断为不同单词，在墨墨词库中判断为同一个单词。', NULL, 1, 0, '2024-11-06 11:17:09', '2025-07-23 10:15:36', 0);
INSERT INTO `voc_book` VALUES (1854000040462983171, 1853714894941786113, 'SAT词汇', 'SAT巴朗词表乱序版', '李亮、路淑双', '北京语言大学出版社', '9787561939765', 3520, '高频词和热词在核心词汇中分别以□和○标注。', '2015年5月第1版', 2, 0, '2024-11-06 11:17:09', '2024-12-23 12:03:25', 0);
