INSERT INTO `voc_book` VALUES (1854000041251512323, NULL, NULL, '朗文3000常用交流词汇', NULL, NULL, NULL, 3159, 'The Longman Communication 3000 is a list of the 3000 most frequent words in both spoken and written English, based on statistical analysis of the 390 million words contained in the Longman Corpus Network – a group of corpuses or databases of authentic English language. The Longman Communication 3000 represents the core of the English language and shows students of English which words are the most important for them to learn and study in order to communicate effectively in both speech and writing.', NULL, 58, 0, '2024-11-06 11:17:10', '2024-12-23 12:03:25', 0);
