INSERT INTO `voc_book` VALUES (1854000055684112387, 1853715495989743617, '分频词汇', '美国当代语料库 20200', NULL, NULL, NULL, 5118, 'COCA美国当代英语语料库（全称Corpus of Contemporary American English)是当今世界上最大的在线免费英语平衡语料库，由美国杨百翰大学语言学教授Mark Davies在2008年建立，主要为语言学习者和语言学家了解单词、短语以及句子结构的频率及进行相关信息比较而设计。 *缺失部分单词为同一个单词不同词性在美国语料库中判断为不同单词，在墨墨词库中判断为同一个单词。', NULL, 1, 0, '2024-11-06 11:17:13', '2024-12-23 12:03:25', 0);
