DROP TABLE IF EXISTS `user_rev_statistics`;
CREATE TABLE `user_rev_statistics`  (
  `id` bigint NOT NULL COMMENT 'id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `voc_new_count` int NULL DEFAULT NULL COMMENT '复习的旧单词数量',
  `voc_review_count` int NULL DEFAULT NULL COMMENT '复习的新单词数量',
  `total_count` int NULL DEFAULT NULL COMMENT '复习的单词总数量',
  `forget_count` int NULL DEFAULT NULL COMMENT '遗忘单词数量',
  `uncertain_count` int NULL DEFAULT NULL COMMENT '模糊单词数量',
  `known_count` int NULL DEFAULT NULL COMMENT '认识单词数量',
  `simple_count` int NULL DEFAULT NULL COMMENT '简单单词数量',
  `review_date` date NULL DEFAULT NULL COMMENT '复习日期',
  `study_time` bigint NULL DEFAULT NULL COMMENT '学习时间ms为单位',
