  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `free` int NULL DEFAULT 0 COMMENT '免费获得单词上限数量',
  `exchange` int NULL DEFAULT 0 COMMENT '抵扣消耗的单词上限数量',
  `pay` int NULL DEFAULT 0 COMMENT '购买的单词上限数量',
  `total` int NULL DEFAULT NULL COMMENT '总的单词上限数量',
  `occupied` int NULL DEFAULT 0 COMMENT '被占用的单词上限数量',
  `available` int NULL DEFAULT 0 COMMENT '可用的单词上限数量',
