-- ----------------------------
-- Table structure for user_voc_rev
-- ----------------------------
DROP TABLE IF EXISTS `user_voc_rev`;
CREATE TABLE `user_voc_rev`  (
  `id` bigint NOT NULL COMMENT 'id值',
  `voc_id` bigint NULL DEFAULT NULL COMMENT '单词id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `factor` double(10, 2) NULL DEFAULT NULL COMMENT '当前的复习的易度因子',
  `review_interval` int NULL DEFAULT NULL COMMENT '当前复习的时间间隔',
  `next_review_date` date NULL DEFAULT NULL COMMENT '下次复习的日期',
  `type` int NULL DEFAULT NULL COMMENT '0 还未学习 1. 正常复习',
  `familiarity` int NULL DEFAULT NULL COMMENT '0.不认识  1.模糊  2. 认识  3.简单',
  `consecutive_fail_count` int NULL DEFAULT NULL COMMENT '连续失败',
  `total_review` int NULL DEFAULT NULL COMMENT '总的学习次数',
  `current_count` int NULL DEFAULT NULL COMMENT '当前复习次数，连续失败三次清零',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` int NULL DEFAULT 0 COMMENT '逻辑删除字段',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id_voc_id`(`user_id` ASC, `voc_id` ASC) USING BTREE,
  INDEX `idx_user_id_review_interval`(`user_id` ASC, `review_interval` ASC) USING BTREE,
  INDEX `idx_user_id_updated_time`(`user_id` ASC, `updated_time` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

