-- ----------------------------
-- Table structure for voc
-- ----------------------------
DROP TABLE IF EXISTS `voc`;
CREATE TABLE `voc`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '单词id',
  `content` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单词',
  `uk_phonetic` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单词的英式音标',
  `us_phonetic` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单词的美式音标',
  `us_pronounciation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单词的美式发音文件url',
  `uk_pronounciation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '单词的英式发音文件url',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` int NULL DEFAULT 0 COMMENT '删除标识: 0 未删除 1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_content`(`content` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1930237458021478402 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

