CREATE TABLE `voc_meaning`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '单词释义id',
  `voc_id` bigint NULL DEFAULT NULL COMMENT '单词id',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '1.n  2.pron  3. verb 4. adj  5. adv 6. prep 7. conj 8. int ',
  `inter_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '释义内容',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
