-- ----------------------------
-- Table structure for voc_pay_sale
-- ----------------------------
DROP TABLE IF EXISTS `voc_pay_sale`;
CREATE TABLE `voc_pay_sale`  (
  `id` bigint NOT NULL COMMENT '支付交易id',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
  `item_id` bigint NULL DEFAULT NULL COMMENT '如果是等级就是等级id，特权就是特权id，商品就是商品id',
  `item_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称',
  `item_type` int NULL DEFAULT NULL COMMENT '1.  单词上限 2. 等级解锁 3.补签卡 ',
  `pay_price` decimal(10, 0) NULL DEFAULT NULL COMMENT '价格',
  `status` int NULL DEFAULT NULL COMMENT '1. 初始化  2. 支付成功',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` int NULL DEFAULT 0 COMMENT '逻辑删除状态: 0未删除 1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

